-- =====================================================================
-- Stage weights for the batch 5 root causes (industries 21-25).
--
-- Unlike batches 1-4, this uses the PER-DIMENSION curve from the start.
-- Those batches were written with one flat curve for every cause, which put
-- all of them at the maximum 2.00 at Early Traction and handed the new
-- content a ranking advantage over the original catalogue.
-- fix_stage_weight_curves.sql corrects them; batch 5 never needs correcting.
--
-- stage_weight answers "how relevant is this cause at this stage", which is a
-- property of the DIMENSION. At Early Traction these curves average 1.556
-- against the original catalogue's 1.557 -- parity, not advantage.
--
-- Idempotent, no hardcoded ids: causes resolved by code, ON CONFLICT DO NOTHING.
-- =====================================================================
BEGIN;
-- Repair the sequence ONLY if it is actually behind its own table.
--
-- An earlier version called setval() unconditionally. setval() needs UPDATE on
-- the sequence, and a migration role that has INSERT on the tables and only
-- USAGE on the sequence does not have it -- so the call failed with
-- "permission denied for sequence root_cause_weights_weight_id_seq" and took
-- the whole transaction with it, before a single row was inserted. Raised by
-- the AWS team from a permission problem they had already hit once.
--
-- INSERT itself only needs nextval(), which USAGE alone allows. So the repair
-- is needed only in the one case where the sequence sits behind max(weight_id)
-- -- which happens when rows were loaded with explicit ids, as the original
-- catalogue was via Supabase. If the sequence is already ahead, this does
-- nothing and needs no privilege at all.
do $$
declare
  seq text := pg_get_serial_sequence('root_cause_weights','weight_id');
  mx  bigint;
  cur bigint;
begin
  select coalesce(max(weight_id), 0) into mx from root_cause_weights;
  cur := pg_sequence_last_value(seq::regclass);

  if cur is not null and cur >= mx then
    raise notice 'sequence is ahead of the table (sequence %, max id %) -- no repair needed.', cur, mx;
    return;
  end if;

  begin
    perform setval(seq, greatest(mx, 1));
    raise notice 'sequence repaired: moved to % (was %).', greatest(mx, 1), coalesce(cur::text, 'unused');
  exception
    when insufficient_privilege then
      raise exception
        'The sequence % is behind its table (highest weight_id is %, sequence is at %), '
        'and this role cannot run setval on it. Inserting now would collide on the primary key. '
        'Either grant the privilege:  GRANT USAGE, UPDATE ON SEQUENCE % TO current_user;  '
        'or have the table owner run:  SELECT setval(''%'', %);  '
        'then re-run this file. Nothing has been changed.',
        seq, mx, coalesce(cur::text, 'unused'), seq, seq, greatest(mx, 1);
  end;
end $$;

-- LOG

-- MKT

-- NGO

-- PHM

-- SVC

do $$
declare short int; total int; s4 numeric;
begin
  select count(*) into short from (
    select rc.root_cause_id from root_causes rc
      left join root_cause_weights w on w.root_cause_id = rc.root_cause_id
     where rc.root_cause_code ~ '^RC-(LOG|MKT|NGO|PHM|SVC)-3[0-9][0-9]-[0-9]$'
     group by rc.root_cause_id having count(w.weight_id) <> 8) x;
  select count(*) into total from root_causes
   where root_cause_code ~ '^RC-(LOG|MKT|NGO|PHM|SVC)-3[0-9][0-9]-[0-9]$';
  if total <> 135 then
    raise exception 'expected 135 batch 5 root causes, found % -- load batch5_industries_21to25.sql first', total;
  end if;
  if short > 0 then
    raise exception 'stage weights incomplete: % batch 5 root causes do not have 8 rows', short;
  end if;
  select round(avg(w.stage_weight),3) into s4 from root_cause_weights w
    join root_causes rc on rc.root_cause_id = w.root_cause_id
   where rc.root_cause_code ~ '^RC-(LOG|MKT|NGO|PHM|SVC)-3[0-9][0-9]-[0-9]$' and w.stage_id = 4;
  if s4 > 1.7 then
    raise exception 'batch 5 Early Traction mean is % -- the flat curve is back, not the per-dimension one', s4;
  end if;
  raise notice 'batch 5 stage weights ok: 135 causes x 8 stages, Early Traction mean % (parity with catalogue).', s4;
end $$;
COMMIT;
